steps.command:
nc -z -w 3 localhost 2222; echo PORT_RC=$?; cat > /tmp/sshtest.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 30
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no root@localhost
expect {
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)are you sure you want to continue connecting" { send "yes\r"; exp_continue }
  "#" { send "echo SSH_OK; uname -a; id; poweroff\r"; expect eof }
  eof {}
}
EOF
chmod +x /tmp/sshtest.exp; expect -f /tmp/sshtest.exp 2>&1 | tail -30

cat > /tmp/sshtest2.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 30
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o PreferredAuthentications=password -o PubkeyAuthentication=no root@localhost
expect {
  -re "(?i)password:" { send "password123\r"; exp_continue }
  -re "(?i)are you sure you want to continue connecting" { send "yes\r"; exp_continue }
  "#" { send "echo LOGIN_OK; id; exit\r"; expect eof }
  timeout { puts "TIMEOUT"; exit 1 }
  eof { puts "EOF"; exit 2 }
}
EOF
expect -f /tmp/sshtest2.exp 2>&1 | tail -20; echo TEST_RC=${PIPESTATUS[0]}; nc -z -w 3 localhost 2222; echo PORT_RC=$?
